intro.sandboxCode:
class Task {
  constructor(id, title) {
    this.id = id
    this.title = title
    this.done = false
    this.tags = []
    this.due = null
  }
  toggle() {
    this.done = !this.done
  }
  toString() {
    return `[${this.done ? "x" : " "}] ${this.title}`
  }
}

const t = new Task(1, "Water the plants")
console.log(t.toString())
t.toggle()
console.log(t.toString())

challenges.solution:
class Task {
  constructor(id, title) {
    this.id = id
    this.title = title
    this.done = false
    this.tags = []
    this.due = null
  }
  toggle() {
    this.done = !this.done
  }
  toString() {
    return `[${this.done ? "x" : " "}] ${this.title}`
  }
}

function parseTask(text) {
  const tags = [...text.matchAll(/#(\w+)/g)].map((m) => m[1])
  const due = text.match(/due:(\d{4}-\d{2}-\d{2})/)?.[1] ?? null
  const title = text.replace(/#\w+|due:\S+/g, "").replace(/\s+/g, " ").trim()
  return { title, tags, due }
}

