challenges.solution:
class Task {
  constructor(id, title) {
    this.id = id
    this.title = title
    this.done = false
    this.tags = []
    this.due = null
  }
  toggle() {
    this.done = !this.done
  }
  toString() {
    return `[${this.done ? "x" : " "}] ${this.title}`
  }
}
function parseTask(text) {
  const tags = [...text.matchAll(/#(\w+)/g)].map((m) => m[1])
  const due = text.match(/due:(\d{4}-\d{2}-\d{2})/)?.[1] ?? null
  const title = text.replace(/#\w+|due:\S+/g, "").replace(/\s+/g, " ").trim()
  return { title, tags, due }
}
class TaskList {
  constructor() {
    this.tasks = []
    this.nextId = 1
  }
  add(text) {
    const { title, tags, due } = parseTask(text)
    const task = new Task(this.nextId++, title)
    task.tags = tags
    task.due = due
    this.tasks.push(task)
    return task
  }
  find(id) {
    const task = this.tasks.find((t) => t.id === id)
    if (!task) throw new Error(`No task ${id}`)
    return task
  }
  remove(id) {
    this.find(id)
    this.tasks = this.tasks.filter((t) => t.id !== id)
  }
}

