class Task {
  constructor(id, title) {
    this.id = id
    this.title = title
    this.done = false
    this.tags = []
    this.due = null
  }
  toggle() {
    this.done = !this.done
  }
  toString() {
    return `[${this.done ? "x" : " "}] ${this.title}`
  }
}
function parseTask(text) {
  const tags = [...text.matchAll(/#(\w+)/g)].map((m) => m[1])
  const due = text.match(/due:(\d{4}-\d{2}-\d{2})/)?.[1] ?? null
  const title = text.replace(/#\w+|due:\S+/g, "").replace(/\s+/g, " ").trim()
  return { title, tags, due }
}
class TaskList {
  constructor() {
    this.tasks = []
    this.nextId = 1
  }
  add(text) {
    const { title, tags, due } = parseTask(text)
    const task = new Task(this.nextId++, title)
    task.tags = tags
    task.due = due
    this.tasks.push(task)
    return task
  }
  find(id) {
    const task = this.tasks.find((t) => t.id === id)
    if (!task) throw new Error(`No task ${id}`)
    return task
  }
  remove(id) {
    this.find(id)
    this.tasks = this.tasks.filter((t) => t.id !== id)
  }
  active() {
    return this.tasks.filter((t) => !t.done)
  }
  completed() {
    return this.tasks.filter((t) => t.done)
  }
}
const list = new TaskList()
list.add("Buy milk #home due:2026-11-10")
list.add("Send report #work due:2026-11-12")
list.add("Book dentist due:2026-12-01")
list.add("Read a book #home")
list.find(2).toggle()
function render(list, today) {
  const groupOf = (t) => {
    if (t.due === null) return "No date"
    if (t.due === today) return "Today"
    if (t.due < today) return t.done ? null : "Overdue"
    return "Later"
  }
  for (const group of ["Overdue", "Today", "Later", "No date"]) {
    const tasks = list.tasks.filter((t) => groupOf(t) === group)
    if (tasks.length === 0) continue
    console.log(group)
    for (const t of tasks) {
      const tags = t.tags.map((tag) => ` #${tag}`).join("")
      const due = t.due && group !== "Today" ? ` (${t.due})` : ""
      console.log(`  ${t}${tags}${due}`)
    }
  }
}
render(list, "2026-11-12")

