  { "id": 1, "category": "space", "q": "Which planet is known as the red planet?", "a": "Mars" },
  { "id": 2, "category": "space", "q": "What is the largest planet?", "a": "Jupiter" },
  { "id": 3, "category": "nature", "q": "How many legs does a spider have?", "a": "8", "accept": ["eight"] },
  { "id": 4, "category": "space", "q": "What do we call a rock that burns up in the sky?", "a": "meteor", "accept": ["shooting star"] },
  { "id": 5, "category": "nature", "q": "What is the largest ocean?", "a": "Pacific", "accept": ["Pacific Ocean"] },
  { "id": 6, "category": "nature", "q": "What gas do plants take in?", "a": "carbon dioxide", "accept": ["CO2"] }
]`
const bank = JSON.parse(bankJson)
function isRight(question, answer) {
  const clean = (s) => String(s).trim().replace(/\s+/g, " ").toLowerCase()
  return [question.a, ...(question.accept ?? [])].some((ok) => clean(ok) === clean(answer))
}

