async function answerWithin(getAnswer, question, ms) {
  const timeUp = new Promise((resolve) => setTimeout(() => resolve(null), ms))
  return Promise.race([getAnswer(question), timeUp])
}

function addHighScore(table, name, points) {
  let at = table.findIndex((e) => e.points < points)
  if (at === -1) at = table.length
  const next = table.toSpliced(at, 0, { name, points }).slice(0, 5)
  return { table: next, rank: at < 5 ? at + 1 : null }
}

