  products: {
    mug: { id: "mug", name: "Mug", price: 8.5, stock: 5 },
    tee: { id: "tee", name: "T-shirt", price: 19.99, stock: 2 },
    cap: { id: "cap", name: "Cap", price: 12, stock: 0 },
    pen: { id: "pen", name: "Pen", price: 1.25, stock: 40 },
  },
  async getProduct(id) {
    await new Promise((r) => setTimeout(r, 5))
    const p = this.products[id]
    if (!p) throw new Error(`No product ${id}`)
    return { ...p }
  },
  async reserve(id, qty) {
    await new Promise((r) => setTimeout(r, 5))
    const p = this.products[id]
    if (p.stock < qty) throw new Error(`Only ${p.stock} left of ${p.name}`)
    p.stock -= qty
  },
  async release(id, qty) {
    await new Promise((r) => setTimeout(r, 5))
    this.products[id].stock += qty
  },
}
class Cart {
  constructor() {
    this.lines = []
  }
  add(product, qty = 1) {
    const line = this.lines.find((l) => l.product.id === product.id)
    if (line) line.qty += qty
    else this.lines.push({ product, qty })
    return this
  }
  subtotal() {
    const sum = this.lines.reduce((s, l) => s + l.product.price * l.qty, 0)
    return Math.round(sum * 100) / 100
  }
}
async function stockProblems(cart) {
  const fresh = await Promise.all(cart.lines.map((l) => shop.getProduct(l.product.id)))
  return fresh
    .filter((p, i) => p.stock < cart.lines[i].qty)
    .map((p) => `Only ${p.stock} left of ${p.name}`)
}

