  const sub = cart.subtotal()
  const off = code ? discount(code, sub) : 0
  const afterDiscount = Math.round((sub - off) * 100) / 100
  const shipping = afterDiscount >= FREE_SHIPPING_FROM ? 0 : SHIPPING
  return { subtotal: sub, discount: off, shipping, total: Math.round((afterDiscount + shipping) * 100) / 100 }
}
