  const percent = code.match(/^SAVE(\d{1,2})$/)
  if (percent) return Math.round(subtotal * Number(percent[1])) / 100
  const fixed = code.match(/^TAKE(\d+)$/)
  if (fixed) return Math.min(Number(fixed[1]), subtotal)
  throw new Error(`Unknown code ${code}`)
}
const FREE_SHIPPING_FROM = 50
const SHIPPING = 4.5
function total(cart, code) {
  const sub = cart.subtotal()
  const off = code ? discount(code, sub) : 0
  const afterDiscount = Math.round((sub - off) * 100) / 100
  const shipping = afterDiscount >= FREE_SHIPPING_FROM ? 0 : SHIPPING
  return { subtotal: sub, discount: off, shipping, total: Math.round((afterDiscount + shipping) * 100) / 100 }
}
const eur = new Intl.NumberFormat("en-IE", { style: "currency", currency: "EUR" })
async function loadCart(wanted) {
  const entries = Object.entries(wanted)
  const products = await Promise.all(entries.map(([id]) => shop.getProduct(id)))
  const cart = new Cart()
  products.forEach((p, i) => cart.add(p, entries[i][1]))
  return cart
}
