  constructor() {
    this.lines = []
  }
  add(product, qty = 1) {
    const line = this.lines.find((l) => l.product.id === product.id)
    if (line) line.qty += qty
    else this.lines.push({ product, qty })
    return this
  }
  subtotal() {
    const sum = this.lines.reduce((s, l) => s + l.product.price * l.qty, 0)
    return Math.round(sum * 100) / 100
  }
}
function discount(code, subtotal) {
  const percent = code.match(/^SAVE(\d{1,2})$/)
  if (percent) return Math.round(subtotal * Number(percent[1])) / 100
  const fixed = code.match(/^TAKE(\d+)$/)
  if (fixed) return Math.min(Number(fixed[1]), subtotal)
  throw new Error(`Unknown code ${code}`)
}
const FREE_SHIPPING_FROM = 50
const SHIPPING = 4.5
function total(cart, code) {
  const sub = cart.subtotal()
  const off = code ? discount(code, sub) : 0
  const afterDiscount = Math.round((sub - off) * 100) / 100
  const shipping = afterDiscount >= FREE_SHIPPING_FROM ? 0 : SHIPPING
  return { subtotal: sub, discount: off, shipping, total: Math.round((afterDiscount + shipping) * 100) / 100 }
}
const eur = new Intl.NumberFormat("en-IE", { style: "currency", currency: "EUR" })
async function loadCart(wanted) {
  const entries = Object.entries(wanted)
  const products = await Promise.all(entries.map(([id]) => shop.getProduct(id)))
  const cart = new Cart()
  products.forEach((p, i) => cart.add(p, entries[i][1]))
  return cart
}
async function checkout(cart) {
  const done = []
  try {
    for (const line of cart.lines) {
      await shop.reserve(line.product.id, line.qty)
      done.push(line)
    }
  } catch (e) {
    for (const line of done) await shop.release(line.product.id, line.qty)
    throw e
  }
  return "Order placed"
}
async function placeOrder(wanted, code) {
  try {
    const cart = await loadCart(wanted)
    const t = total(cart, code)
    const problems = cart.lines.filter((l) => l.product.stock < l.qty).map((l) => `Only ${l.product.stock} left of ${l.product.name}`)
    if (problems.length > 0) return `Sorry: ${problems.join("; ")}`
    await checkout(cart)
    return `Order placed: ${eur.format(t.total)}`
  } catch (e) {
    return `Sorry: ${e.message}`
  }
}

