challenges.solution:
function tick(log, habit, date) {
  const name = habit.trim().toLowerCase()
  if (log.some((e) => e.habit === name && e.date === date)) return log
  return [...log, { habit: name, date }]
}

function expectEqual(label, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected)
  return ok ? `PASS ${label}` : `FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`
}

function checkEntry(entry) {
  if (!entry.habit || entry.habit.trim() === "") throw new Error("No habit")
  const date = entry.date
  const real = /^\d{4}-\d{2}-\d{2}$/.test(date ?? "") && !Number.isNaN(Date.parse(date)) && new Date(date + "T00:00:00Z").toISOString().slice(0, 10) === date
  if (!real) throw new Error(`Bad date: ${date}`)
