challenges.solution:
async function sync(log, send) {
  let last
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      await send(JSON.stringify(log))
      return `Saved ${log.length} entries`
    } catch (e) {
      last = e
    }
  }
  return `Not saved: ${last.message}`
}

